package io.knowledgebrain.planning;
import java.time.*;import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.flywaydb.core.Flyway;import org.springframework.jdbc.core.JdbcTemplate;import org.apache.kafka.clients.consumer.*;
import io.knowledgebrain.contracts.planning.delivery.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP",matches=".+")
class ReminderDeliveryKafkaIntegrationTest {
 @Test void durableArmedCancelledAndDispatchedAttemptsReachKafkaWithExactSourceBytes()throws Exception{var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var time=new ReminderDeliveryIntegrationTest.Time();var ids=new UuidV7(time);var space=ids.next();var actor=ids.next();String trace="d".repeat(32);var schedules=new ScheduleStore(ds,time);var reminders=new ReminderStore(ds,time);var delivery=new ReminderDeliveryStore(ds,time);var s=schedules.create(space,actor,UUID.randomUUID().toString().replace("-",""),new ScheduleStore.Input("Kafka in-app dispatch","","2028-01-01T00:02:00Z","2028-01-01T00:03:00Z","UTC",null),trace).schedule();var i=new ReminderRules.Input(s.scheduleId(),1,1);var m=reminders.create(space,actor,UUID.randomUUID().toString().replace("-",""),i,reminders.preview(space,i).previewHash(),trace).reminder();var a=delivery.arm(space,m.reminderId(),actor,1,UUID.randomUUID().toString().replace("-",""),trace).delivery();delivery.cancel(space,m.reminderId(),a.deliveryId(),actor,1,trace);var b=delivery.arm(space,m.reminderId(),actor,1,UUID.randomUUID().toString().replace("-",""),trace).delivery();time.advance(61);assertTrue(delivery.process(b.deliveryId()));var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),a.deliveryId(),b.deliveryId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(4,expected.size());
 var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_PLANNING_KAFKA_BOOTSTRAP"));p.put("group.id","planning-validation-"+ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/planning-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/planning-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/planning-kafka-test/user.key")));
 try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("planning.reminder-delivery.v1"));var found=new HashSet<String>();long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){if(!Set.of(a.deliveryId().toString(),b.deliveryId().toString()).contains(row.key()))continue;var e=ReminderDeliveryEnvelopeV1.parseFrom(row.value());assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals(space.toString(),e.getSpaceId());assertEquals(actor.toString(),e.getActorId());assertEquals("planning-service",e.getProducer());assertEquals("ReminderDelivery",e.getAggregateType());var v=ReminderDeliveryPayloadV1.parseFrom(e.getPayload());assertEquals(s.scheduleId().toString(),v.getScheduleId());assertEquals(m.remindsAt(),v.getRemindsAt());assertEquals(1,v.getReminderVersion());for(var h:Map.of("id",e.getEventId(),"trace_id",trace,"schema_group","planning","schema_artifact","reminder-delivery-events","schema_version","1").entrySet())assertEquals(h.getValue(),new String(row.headers().lastHeader(h.getKey()).value(),StandardCharsets.UTF_8));found.add(e.getEventId());}assertEquals(expected.keySet(),found);}
 }
}
